// Content with portions generated by generative AI platform
package org.eclipse.kura.container.orchestration.provider.impl.enforcement;

import java.util.Arrays;
import java.util.Collections;
import java.util.Set;
import java.util.stream.Collectors;

final class Allowlist {

    private final Set<String> digests;

    private Allowlist(Set<String> digests) {
        this.digests = digests;
    }

    static Allowlist parse(String content) {
        return new Allowlist(Arrays.stream(content.replace(" ", "").split("\\r?\\n|\\r"))
                .filter(line -> !line.isEmpty()).collect(Collectors.collectingAndThen(Collectors.toSet(), Collections::unmodifiableSet)));
    }

    int size() {
        return this.digests.size();
    }

    Set<String> digestsAllowing(Set<String> imageDigests) {
        return this.digests.stream().filter(imageDigests::contains).collect(Collectors.toSet());
    }
}
